from pathlib import Path
p=Path('NullSignalMVP/app/src/main/java/com/nullsignal/local/MainActivity.java');x=p.read_text()
freq='''        section("FREQUENT COMMUTES");List<MobilityStore.TransitionRow> trs=ms.topTransitions(8);if(trs.isEmpty()){LinearLayout e=card();e.addView(text("No repeated commute pairs learned yet",15,TEXT,true));e.addView(text("After several trips between the same places, personal average travel time becomes your ETA and delay baseline.",13,MUTED,false));root.addView(e);}else for(MobilityStore.TransitionRow tr:trs)root.addView(commutePatternCard(tr));spacer(14);\n\n'''
x=x.replace('        section("RECENT JOURNEYS");',freq+'        section("RECENT JOURNEYS");')
old='row.addView(map,lp);c.addView(row);margin(c);return c;}'
new='row.addView(map,lp);c.addView(row);c.addView(actionButton("Wake / alert me ~800 m before this place",v->{NullSignalDb.get(this).putState("approach_target_place",String.valueOf(p.id));NullSignalDb.get(this).putState("approach_radius_m","800");NullSignalDb.get(this).putState("approach_closest_m","");NullSignalDb.get(this).putState("approach_overshoot_alerted","0");toast("Arrival alarm armed for "+p.display());render();}));margin(c);return c;}'
