helper='''    private View commutePatternCard(MobilityStore.TransitionRow tr){MobilityStore ms=MobilityStore.get(this);MobilityStore.PlaceRow a=ms.getPlace(tr.startPlaceId),b=ms.getPlace(tr.endPlaceId);LinearLayout c=card();c.addView(text((a==null?"Place "+tr.startPlaceId:a.display())+" → "+(b==null?"Place "+tr.endPlaceId:b.display()),15,TEXT,true));c.addView(text(tr.count+" trips · average "+formatDuration((long)tr.meanDuration())+" · variation ±"+formatDuration((long)tr.sdDuration()),12,CYAN,false));c.addView(text(tr.dayType+" · "+tr.part,11,MUTED,false));margin(c);return c;}\n    private String friendlyMode(String m){if(m==null||m.isEmpty())return "unknown";if("mixed commute".equals(m))return "walking + public transit";return m;}\n'''
